<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    x-axis [&quot;RESTOR&quot;, &quot;GPT-4提示&quot;, &quot;GPT-3.5提示&quot;, &quot;RESTler&quot;]</span></span>
